ALTER TABLE club_event ADD COLUMN settlement_mode varchar(20) NOT NULL DEFAULT 'POSTPAY' CHECK(settlement_mode IN ('PREPAY','POSTPAY'));
ALTER TABLE club_event ADD COLUMN schedule_version bigint NOT NULL DEFAULT 1;
ALTER TABLE event_round ADD COLUMN fee_version bigint NOT NULL DEFAULT 1;
ALTER TABLE event_round ADD COLUMN status varchar(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED','CANCELLED'));
ALTER TABLE participation ADD COLUMN agreed_fee_version bigint NOT NULL DEFAULT 1;
ALTER TABLE participation ADD COLUMN agreed_at timestamptz;
ALTER TABLE participation ADD COLUMN fee_consent varchar(20) NOT NULL DEFAULT 'ACCEPTED' CHECK(fee_consent IN ('ACCEPTED','PENDING','REJECTED'));
ALTER TABLE participation ADD COLUMN schedule_consent varchar(20) NOT NULL DEFAULT 'ACCEPTED' CHECK(schedule_consent IN ('ACCEPTED','PENDING','REJECTED'));
ALTER TABLE participation ADD COLUMN schedule_version bigint NOT NULL DEFAULT 1;
ALTER TABLE participation ADD COLUMN waived_reason varchar(100);
CREATE TABLE settlement_book(id uuid PRIMARY KEY,version bigint NOT NULL,event_id uuid NOT NULL UNIQUE REFERENCES club_event(id),status varchar(20) NOT NULL CHECK(status IN ('OPEN','REGISTERED','CLOSED')),mode varchar(20) NOT NULL CHECK(mode IN ('PREPAY','POSTPAY')),first_registered_at timestamptz,final_deadline timestamptz);
CREATE TABLE round_billing(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),round_id uuid NOT NULL UNIQUE REFERENCES event_round(id),amount bigint NOT NULL CHECK(amount BETWEEN 0 AND 9007199254740991),deadline timestamptz NOT NULL,closed boolean NOT NULL);
CREATE TABLE billing_history(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),round_id uuid NOT NULL REFERENCES event_round(id),amount bigint NOT NULL CHECK(amount BETWEEN 0 AND 9007199254740991),deadline timestamptz NOT NULL,created_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id));
CREATE TABLE payment_request(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),round_id uuid REFERENCES event_round(id),user_id uuid NOT NULL REFERENCES app_user(id),amount bigint NOT NULL CHECK(amount BETWEEN 0 AND 9007199254740991),deadline timestamptz,status varchar(20) NOT NULL CHECK(status IN ('ACTIVE','SUPERSEDED')));
CREATE UNIQUE INDEX request_round_user ON payment_request(book_id,round_id,user_id) WHERE round_id IS NOT NULL;
CREATE UNIQUE INDEX request_final_user ON payment_request(book_id,user_id) WHERE round_id IS NULL;
CREATE TABLE request_extension(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),request_id uuid NOT NULL REFERENCES payment_request(id),previous_deadline timestamptz,deadline timestamptz NOT NULL,reason varchar(1000) NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id),created_at timestamptz NOT NULL,CHECK(deadline>previous_deadline));
CREATE TABLE payment_report(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),request_id uuid NOT NULL REFERENCES payment_request(id),user_id uuid NOT NULL REFERENCES app_user(id),reported_amount bigint NOT NULL CHECK(reported_amount BETWEEN 1 AND 9007199254740991),amount bigint NOT NULL CHECK(amount BETWEEN 0 AND 9007199254740991),status varchar(20) NOT NULL CHECK(status IN ('PENDING','VERIFIED','REJECTED')),evidence text,reason varchar(1000),transaction_reference varchar(200),reported_at timestamptz NOT NULL,actual_received_at timestamptz,processed_at timestamptz,processed_by uuid REFERENCES app_user(id));

CREATE TABLE finance_bank_transaction(id uuid PRIMARY KEY,version bigint NOT NULL,reference varchar(200) NOT NULL,account_scope varchar(200) NOT NULL,scope_kind varchar(30) NOT NULL,actual_actor_id uuid NOT NULL REFERENCES app_user(id),cash_account_id uuid,book_id uuid REFERENCES settlement_book(id),record_id uuid NOT NULL,kind varchar(20) NOT NULL CHECK(kind IN ('RECEIPT','REFUND','MOVEMENT')),UNIQUE(account_scope,reference));
CREATE TABLE finance_revision(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),reason varchar(1000) NOT NULL,snapshot text NOT NULL,after_snapshot text,created_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id));
CREATE TABLE receipt_correction(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),report_id uuid NOT NULL REFERENCES payment_report(id),revision_id uuid NOT NULL REFERENCES finance_revision(id),amount bigint NOT NULL CHECK(amount BETWEEN 0 AND 9007199254740991),actual_received_at timestamptz,reason varchar(1000) NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id),created_at timestamptz NOT NULL,sequence bigint NOT NULL,UNIQUE(book_id,sequence));
CREATE TABLE receipt_allocation(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),report_id uuid NOT NULL REFERENCES payment_report(id),correction_id uuid REFERENCES receipt_correction(id),round_id uuid NOT NULL REFERENCES event_round(id),kind varchar(20) NOT NULL CHECK(kind IN ('ATTENDANCE','CANCELLATION','HOST_CONTRIBUTION')),amount bigint NOT NULL CHECK(amount BETWEEN 1 AND 9007199254740991));
CREATE TABLE finance_expense(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),round_id uuid NOT NULL REFERENCES event_round(id),revision_id uuid REFERENCES finance_revision(id),paid_by_user_id uuid REFERENCES app_user(id),title varchar(100) NOT NULL,amount bigint NOT NULL CHECK(amount BETWEEN -9007199254740991 AND 9007199254740991),evidence text,created_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id),CHECK(amount>=0 OR revision_id IS NOT NULL));
CREATE TABLE finance_adjustment(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),revision_id uuid NOT NULL REFERENCES finance_revision(id),round_id uuid NOT NULL REFERENCES event_round(id),user_id uuid NOT NULL REFERENCES app_user(id),amount bigint NOT NULL CHECK(amount BETWEEN -9007199254740991 AND 9007199254740991));
CREATE TABLE finance_refund(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),user_id uuid NOT NULL REFERENCES app_user(id),amount bigint NOT NULL CHECK(amount BETWEEN 1 AND 9007199254740991),sent_amount bigint NOT NULL CHECK(sent_amount BETWEEN 0 AND 9007199254740991),status varchar(20) NOT NULL CHECK(status IN ('REQUESTED','SENT','CONFIRMED')),requested_at timestamptz NOT NULL,requested_by uuid NOT NULL REFERENCES app_user(id),sent_at timestamptz,sent_by uuid REFERENCES app_user(id),confirmed_at timestamptz,transaction_reference varchar(200));
CREATE TABLE finance_fee_credit(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),participation_id uuid NOT NULL REFERENCES participation(id),baseline bigint NOT NULL CHECK(baseline>=0),credited_late bigint NOT NULL CHECK(credited_late>=0),reserved_late bigint NOT NULL CHECK(reserved_late>=0),UNIQUE(book_id,participation_id));
CREATE TABLE finance_dispute(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),user_id uuid NOT NULL REFERENCES app_user(id),status varchar(20) NOT NULL CHECK(status IN ('OPEN','REVIEWING','ACCEPTED','REJECTED','WITHDRAWN')),reason text NOT NULL,evidence text,resolution varchar(1000),public_result varchar(1000),correction_amount bigint NOT NULL,revision_id uuid REFERENCES finance_revision(id),created_at timestamptz NOT NULL,resolved_at timestamptz,resolved_by uuid REFERENCES app_user(id));
CREATE TABLE round_fee_term(id uuid PRIMARY KEY,version bigint NOT NULL,round_id uuid NOT NULL REFERENCES event_round(id),term_version bigint NOT NULL,fee bigint NOT NULL CHECK(fee BETWEEN 0 AND 9007199254740991),created_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id),reason varchar(1000) NOT NULL,UNIQUE(round_id,term_version));
CREATE TABLE participation_consent(id uuid PRIMARY KEY,version bigint NOT NULL,participation_id uuid NOT NULL REFERENCES participation(id),kind varchar(20) NOT NULL CHECK(kind IN ('FEE','SCHEDULE')),term_version bigint NOT NULL,decision varchar(20) NOT NULL CHECK(decision IN ('ACCEPTED','REJECTED','PENDING')),fee bigint NOT NULL CHECK(fee BETWEEN 0 AND 9007199254740991),created_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id));
CREATE TABLE participation_change(id uuid PRIMARY KEY,version bigint NOT NULL,event_id uuid NOT NULL REFERENCES club_event(id),participation_id uuid NOT NULL REFERENCES participation(id),revision_id uuid REFERENCES finance_revision(id),old_status varchar(20),new_status varchar(20) NOT NULL,old_fee bigint NOT NULL,new_fee bigint NOT NULL,fee_version bigint NOT NULL,waived_reason varchar(100),reason varchar(1000) NOT NULL,created_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id));
CREATE TABLE event_schedule_change(id uuid PRIMARY KEY,version bigint NOT NULL,event_id uuid NOT NULL REFERENCES club_event(id),term_version bigint NOT NULL,old_starts_at timestamptz NOT NULL,old_ends_at timestamptz NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,reason varchar(1000) NOT NULL,created_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id),UNIQUE(event_id,term_version));
CREATE INDEX report_book_idx ON payment_report(book_id); CREATE INDEX allocation_book_idx ON receipt_allocation(book_id,report_id,correction_id); CREATE INDEX correction_report_idx ON receipt_correction(report_id,sequence); CREATE INDEX expense_book_idx ON finance_expense(book_id); CREATE INDEX dispute_book_idx ON finance_dispute(book_id);


CREATE TABLE finance_case_transition(id uuid PRIMARY KEY,version bigint NOT NULL,dispute_id uuid NOT NULL REFERENCES finance_dispute(id),status varchar(20) NOT NULL,reason varchar(1000) NOT NULL,created_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id));

ALTER TABLE finance_dispute ADD COLUMN requested_participation_id uuid REFERENCES participation(id); ALTER TABLE finance_dispute ADD COLUMN requested_status varchar(20);
ALTER TABLE finance_dispute ADD COLUMN counterparty_id uuid REFERENCES app_user(id);
CREATE TABLE finance_expense_funding(id uuid PRIMARY KEY,version bigint NOT NULL,book_id uuid NOT NULL REFERENCES settlement_book(id),expense_id uuid NOT NULL REFERENCES finance_expense(id),paid_by_user_id uuid NOT NULL REFERENCES app_user(id),revision_id uuid REFERENCES finance_revision(id),source varchar(20) NOT NULL CHECK(source IN ('PERSONAL','EVENT_FUNDS')),amount bigint NOT NULL CHECK(amount BETWEEN -9007199254740991 AND 9007199254740991 AND amount<>0),actual_paid_at timestamptz,created_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES app_user(id));
CREATE INDEX funding_book_actor_idx ON finance_expense_funding(book_id,paid_by_user_id);
ALTER TABLE payment_request ADD COLUMN last_additional bigint NOT NULL DEFAULT 0;
